def endpoint_selection_audit(inputs,current,reasons):
    packet=inputs.get('endpoint_selection_audit')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('endpoint audit packet changed')
    if current is None or reasons is None or packet['current_digest']!=digest(current)or packet['reasons_digest']!=digest(reasons):raise ValueError('endpoint audit prior changed')
    if (packet['prior_snapshot'],packet['market_digest'],packet['current_digest'],packet['reasons_digest'])!=(PRIOR_SNAPSHOT,MARKET_DIGEST,CURRENT_DIGEST,REASONS_DIGEST):raise ValueError('endpoint audit frozen baseline changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('endpoint audit market changed')
    sources=packet['sources'];cross={s['symbol']:s for s in sources}
    if len(cross)!=len(sources)or set(cross)!=set(SOURCE_BINDINGS):raise ValueError('endpoint audit source scope changed')
    for code,s in cross.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[code]}!=SOURCE_BINDINGS[code]:raise ValueError('endpoint audit source identity changed')
        if sha256(s['text'].encode()).hexdigest()!=s['sha256']:raise ValueError('endpoint audit response changed')
    fixed=current['full_comparison']['fixed_after']
    if len(fixed['rows'])!=150 or {r['symbol']for r in fixed['rows']}!=set(cross):raise ValueError('endpoint audit fixed cohort changed')
    prices={(r['symbol'],r['trade_date']):r for r in market['fixed_prices']}
    result=[]
    for key,fixed in [('full',current['full_comparison']['fixed_after']),('recent',current['fixed'])]:
     rows=[]
     for r in fixed['rows']:
      code=r['symbol'];s=cross[code];assert sha256(s['text'].encode()).hexdigest()==s['sha256'];b=json.loads(s['text'])['data'][s['provider_key']];quotes=b.get('qfqday')or b.get('day')or[];q={z[0]:z for z in quotes};assert len(q)==len(quotes)
      endpoints=[]
      for side,date in [('anchor',fixed['anchor']),('endpoint',fixed['through'])]:
       primary=prices.get((code,date));other=q.get(date);primary_traded=bool(primary and primary['has_trade'] and D(str(primary.get('raw_volume',0)))>0);cross_traded=bool(other and D(str(other[5]))>0);delta=None if not primary or not other else D(str(primary['close']))-D(str(other[2]));state=r['endpoint_trade_states'][side]['status'];assert (state=='traded')==primary_traded
       status='matched'if primary_traded and cross_traded and abs(delta)<D('1e-9')else'price_basis_or_precision_conflict'if primary_traded and cross_traded else'cross_missing_or_nontraded'if primary_traded else'primary_nontraded_cross_trade_conflict'if cross_traded else'nontraded_or_missing_both'
       endpoints.append(dict(side=side,date=date,primary_state=state,primary_traded=primary_traded,cross_traded=cross_traded,primary_close=None if not primary else str(primary['close']),cross_close=None if not other else str(other[2]),difference=None if delta is None else str(delta),status=status))
      usable=all(z['primary_traded']for z in endpoints);matched=all(z['status']=='matched'for z in endpoints);raw=None;other_ret=None
      if usable:
       a,z=(prices[(code,d)]for d in [fixed['anchor'],fixed['through']]);raw=(D(str(z['close']))/D(str(a['close']))-1)*100;assert r['return_pct']is not None and abs(raw-D(str(r['return_pct'])))<D('1e-9')
      else:assert r['return_pct']is None
      if all(z['cross_traded']for z in endpoints):other_ret=(D(str(q[fixed['through']][2]))/D(str(q[fixed['anchor']][2]))-1)*100
      if matched:assert abs(raw-other_ret)<D('1e-9')
      rows.append(dict(symbol=code,name=r['name'],provider_st_at_end=r['still_st_at_end'],primary_return_pct=None if raw is None else str(raw),certified_return_pct=str(raw)if matched else None,cross_return_pct=None if other_ret is None else str(other_ret),status='matched'if matched else'quote_conflict_or_unverified'if usable else'primary_endpoint_gap',endpoints=endpoints,existing_gap=r['gap'],source_sha256=s['sha256']))
     def stats(rs):
      vals=[D(r['primary_return_pct'])for r in rs if r['primary_return_pct']is not None];good=[D(r['certified_return_pct'])for r in rs if r['certified_return_pct']is not None]
      return dict(members=len(rs),primary_paired=len(vals),primary_missing=len(rs)-len(vals),verified_paired=len(good),unverified_paired=len(vals)-len(good),primary_median_pct=None if not vals else str(median(vals)),verified_subset_median_pct=None if not good else str(median(good)),verified_subset_positive=len([x for x in good if x>0]),verified_subset_positive_denominator=len(good))
     result.append(dict(key=key,anchor=fixed['anchor'],through=fixed['through'],rows=rows,summary=stats(rows),groups=[dict(group='provider_st_at_end',**stats([r for r in rows if r['provider_st_at_end']])),dict(group='provider_not_st_at_end',**stats([r for r in rows if not r['provider_st_at_end']]))]))
